#!/usr/bin/env bash
# Generated by camcfg.py from arterial_32.yaml; edit the inventory and regenerate instead of editing this file.
# Registers the corridor's 8 intersection(s) with the TeraSim TMC collector,
# which pulls camera counts only for registered intersections (once; the registry survives
# restarts, re-registering an id updates it). Run after the chart is installed with this
# corridor's Metadata.json. Needs `oc` logged in to the cluster (KUBECTL=kubectl for plain
# Kubernetes).
set -euo pipefail
KUBECTL="${KUBECTL:-oc}"
TNS="${TNS:-terasim}"                                   # TeraSim namespace
TMC="${TMC:-deploy/terasim-phase1-tmc}"   # the TMC collector Deployment
register() {  # <intersection_id> <name> <lat> <lon>
  "$KUBECTL" exec -n "$TNS" "$TMC" -- python -c 'import json,sys,urllib.request as u
body=json.dumps({"intersection_id":sys.argv[1],"name":sys.argv[2],"lat":float(sys.argv[3]),"lon":float(sys.argv[4])}).encode()
req=u.Request("http://127.0.0.1:8200/v1/tmc/intersections",body,{"Content-Type":"application/json"})
print(u.urlopen(req).read().decode())' "$1" "$2" "$3" "$4"
}
register oak 'Oak St & Arterial Blvd' 37.355 -121.9115
register elm 'Elm St & Arterial Blvd' 37.355 -121.9086751
register pine 'Pine St & Arterial Blvd' 37.355 -121.9058503
register cedar 'Cedar St & Arterial Blvd' 37.355 -121.9030254
register maple 'Maple St & Arterial Blvd' 37.355 -121.9002006
register birch 'Birch St & Arterial Blvd' 37.355 -121.8973757
register ash 'Ash St & Arterial Blvd' 37.355 -121.8945508
register walnut 'Walnut St & Arterial Blvd' 37.355 -121.891726
"$KUBECTL" exec -n "$TNS" "$TMC" -- python -c 'import urllib.request as u;print(u.urlopen("http://127.0.0.1:8200/v1/tmc/health").read().decode())'
